--Verifico año erroneo/nulo

CREATE OR REPLACE FUNCTION public.insertar_anios()
RETURNS void AS
$BODY$
	DECLARE insertar text ='INSERT INTO public.d_anio(anio_id)  VALUES (0);

			BEGIN
			EXECUTE insertar;
			END
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;
ALTER FUNCTION public.insertar_anios()
  OWNER TO postgres; 
  
  
CREATE OR REPLACE FUNCTION public.agregar_anios_faltantes()
RETURNS void AS
$BODY$
DECLARE vAnio integer;
BEGIN
   SELECT min(anio_id) as min_anio INTO vAnio FROM public.d_anio;
   
   IF vAnio <> -1 THEN
	PERFORM public.insertar_anios();  
   END IF;

END;
$BODY$
LANGUAGE plpgsql VOLATILE
COST 100;
ALTER FUNCTION public.agregar_anios_faltantes()
  OWNER TO postgres;
  
Select public.agregar_anios_faltantes();

