--Agrego fechas a la tabla d_fecha
CREATE OR REPLACE FUNCTION public.insertar_fechas()
RETURNS void AS
$BODY$
	DECLARE insertar text = 'INSERT INTO public.d_fecha (fecha_id, anio, mes, dia, dia_semana, dia_semana_desc, dia_semana_abreviada_desc, mes_desc, mes_abreviado_desc, trimestre, trimestre_desc, semestre, semestre_desc, quincena, quincena_desc) VALUES (''2021-01-01'', 2021, 1, 1, 6, ''Viernes'', ''Vie'', ''Enero'', ''Ene'', 1, ''1er Trimestre'', 1, ''1er Semestre'', 1, ''1er Quincena'');

			BEGIN
			EXECUTE insertar;
			END
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;
ALTER FUNCTION public.insertar_fechas()
  OWNER TO postgres; 
  
  
CREATE OR REPLACE FUNCTION public.agregar_fechas()
RETURNS void AS
$BODY$
DECLARE vFecha DATE;
BEGIN
   SELECT max(fecha_id) as max_fecha INTO vFecha FROM public.d_fecha  where fecha_id <> '2199-12-31';
   
   IF vFecha = '2020-12-31' THEN
	PERFORM public.insertar_fechas();  
   END IF;

END;
$BODY$
LANGUAGE plpgsql VOLATILE
COST 100;
ALTER FUNCTION public.agregar_fechas()
  OWNER TO postgres;
  
Select public.agregar_fechas();
